"""Small, privacy-safe feedback component for public research pages."""

from __future__ import annotations


def markup(kind: str = "page", hindi: bool = False) -> str:
    if hindi:
        return f'''<section class="page-feedback" data-page-feedback data-feedback-kind="{kind}" aria-labelledby="page-feedback-title"><h2 id="page-feedback-title">क्या यह पेज उपयोगी था?</h2><p>एक क्लिक का feedback हमें स्रोत, तुलना और missing information बेहतर करने में मदद करता है। कोई account या message जरूरी नहीं।</p><div class="page-feedback-actions"><button type="button" data-feedback-value="helpful">हाँ, उपयोगी था</button><button type="button" data-feedback-value="needs_work">अभी सुधार चाहिए</button></div><div class="page-feedback-reasons" data-feedback-reasons hidden><p>क्या सुधारना चाहिए?</p><button type="button" data-feedback-reason="missing_specs">कुछ specifications missing थीं</button><button type="button" data-feedback-reason="hard_to_choose">चुनना मुश्किल था</button><button type="button" data-feedback-reason="needs_freshness">नई price/stock जानकारी चाहिए</button></div><p class="page-feedback-status" data-feedback-status role="status" aria-live="polite"></p></section>'''
    return f'''<section class="page-feedback" data-page-feedback data-feedback-kind="{kind}" aria-labelledby="page-feedback-title"><h2 id="page-feedback-title">Was this page useful?</h2><p>One-click feedback helps us improve sources, comparisons and missing information. No account or message is required.</p><div class="page-feedback-actions"><button type="button" data-feedback-value="helpful">Yes, it helped</button><button type="button" data-feedback-value="needs_work">Needs improvement</button></div><div class="page-feedback-reasons" data-feedback-reasons hidden><p>What was missing?</p><button type="button" data-feedback-reason="missing_specs">Some specifications were missing</button><button type="button" data-feedback-reason="hard_to_choose">The decision was hard to make</button><button type="button" data-feedback-reason="needs_freshness">I needed newer price/stock information</button></div><p class="page-feedback-status" data-feedback-status role="status" aria-live="polite"></p></section>'''
